def execute(raw):
    """在全新状态执行 raw，返回 (退出码, stdout 字节, stderr 字节)。"""
    try:
        return 0, run(raw), b""
    except _Failure as error:
        return (
            error.exit_code,
            b"",
            ('{"error":"%s"}\n' % error.label).encode("utf-8"),
        )


