    RFC4648 Base64。底层成功或按既有错误失败均产出记录。
    """
    exit_code, out, err = execute(raw)
    record = {
        "version": 1,
        "stdin": base64.b64encode(raw).decode("ascii"),
        "exit": exit_code,
        "stdout": base64.b64encode(out).decode("ascii"),
